{
  "case_id": "xsu_sg_002_permanence_requirement",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret gengiver korrekt definitionen af varig, men udelader at det kun er et udgangspunkt, og udelader tidsbegrænset tillæg ved sandsynliggjort varighed. Det slutter med at den uddannelsessøgende 'skal' have symptomer i mindst et år for at være berettiget. Det gør étårsudgangspunktet til en ubetinget betingelse, og det er en væsentlig fejl efter rubrikken. Svaret nævner heller ikke, at tiden alene ikke afgør spørgsmålet."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "To af fire kritiske elementer mangler eller er svage. Svaret siger ikke, at varigheden vedrører funktionsnedsættelsens art og grad. Det nævner heller ikke tidsbegrænset tillæg, når varighed er sandsynliggjort men ikke endeligt fastslået. Definitionen og étårsreglen er med."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Svaret besvarer, hvornår noget er varigt, og hvad der gælder ved manglende varighed fra begyndelsen. Det besvarer dog ikke fuldt ud, hvad der gælder, når tilstanden ikke er varig fra begyndelsen, fordi muligheden for tidsbegrænset tillæg mangler. Svaret holder sig til emnet, men er ufuldstændigt på en væsentlig del."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken lov, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ingen angivet kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ingen angivet kilde, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret gør étårsudgangspunktet til en ubetinget betingelse ('skal have oplevet ... i mindst et år ... for at være berettiget'). Kilden siger 'som udgangspunkt'. Det er en tilføjet absolut regel, som kilden ikke støtter."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Det første led bevarer ikke 'som udgangspunkt' i definitionen af varig. Det sidste led bevarer ikke 'som udgangspunkt' for étårskravet. Svaret udelader desuden, at tidsforløbet alene ikke afgør varigheden, og at tidsbegrænset tillæg er muligt ved sandsynliggjort varighed."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Trinnene hænger indbyrdes sammen: definition, mulig varighed efter omkring et år og konsekvensen for ansøgningstidspunktet. Der er ingen indre modsigelse, selv om resultatet er for absolut."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret skriver 'skal have oplevet ... for at være berettiget', hvor kilden bruger 'som udgangspunkt'. Det gør en vejledningsbaseret hovedregel absolut. 'Kan vurderes' i det midterste led er dog præcist."
    }
  },
  "xhaile_coverage": {
    "A9": {
      "label": "partial",
      "reason": "Svaret forklarer, hvad en varig funktionsnedsættelse er, men angiver ikke eksplicit, at varighed er en grundlæggende forudsætning for handicaptillæg. Det udelader også, at varigheden vedrører art og grad."
    },
    "A12": {
      "label": "partial",
      "reason": "Svaret dækker, at en ikke-varig tilstand kan vurderes varig efter omkring et år, og at symptomer eller følger skal have varet mindst et år før ansøgningen. Det udelader 'som udgangspunkt' i det sidste led og gør derfor kravet absolut. Det udelader også udgangspunktet om, at man ikke er berettiget, hvis tilstanden ikke fra debut er varig eller kronisk."
    }
  },
  "overall_notes": "Svaret er kort og i store træk korrekt på definitionen og étårspunktet, men det gør étårsudgangspunktet til et ubetinget krav, udelader tidsbegrænset tillæg ved sandsynliggjort varighed og citerer ingen kilde. Det rammer derfor en af rubrikkens væsentlige fejl. C04 er not_met, og C05 og C06 er not_assessable efter reglen om manglende kilde."
}

